<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\Role; use App\Models\User; use App\Services\ApiResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Facades\Password;
class AuthController extends Controller { public function register(Request $r){$d=$r->validate(['name'=>'required|string|max:150','email'=>'nullable|email|max:190|unique:users,email','phone'=>'nullable|string|max:30|unique:users,phone','password'=>'required|string|min:8|confirmed']);$u=User::create([...$d,'password'=>Hash::make($d['password']),'status'=>'active']);if($role=Role::where('slug','contributor')->first())$u->roles()->syncWithoutDetaching([$role->id]);return ApiResponse::ok(['user'=>$u,'token'=>$u->createToken('feni-city-mobile')->plainTextToken],'Registration successful');} public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required|string']);$u=User::where('email',$d['email'])->first();if(!$u||$u->status!=='active'||!Hash::check($d['password'],$u->password))return ApiResponse::error('Invalid credentials',422);return ApiResponse::ok(['user'=>$u,'token'=>$u->createToken('feni-city-mobile')->plainTextToken],'Login successful');} public function logout(Request $r){$r->user()->currentAccessToken()?->delete();return ApiResponse::ok(null,'Logged out successfully');} public function me(Request $r){return ApiResponse::ok($r->user()->load('roles'),'Profile retrieved successfully');} public function update(Request $r){$d=$r->validate(['name'=>'sometimes|string|max:150','phone'=>'sometimes|string|max:30|unique:users,phone,'.$r->user()->id]);$r->user()->update($d);return ApiResponse::ok($r->user()->fresh(),'Profile updated successfully');} public function forgotPassword(Request $r){$d=$r->validate(['email'=>'required|email']);$status=Password::sendResetLink(['email'=>$d['email']]);return ApiResponse::ok(null,$status===Password::RESET_LINK_SENT?'Password reset link sent.':'If the account exists, a reset link will be sent.');} public function resetPassword(Request $r){$d=$r->validate(['email'=>'required|email','token'=>'required','password'=>'required|min:8|confirmed']);$status=Password::reset($d,function($u,$password){$u->forceFill(['password'=>Hash::make($password)])->save();$u->tokens()->delete();});return $status===Password::PASSWORD_RESET?ApiResponse::ok(null,'Password reset successful.'):ApiResponse::error('Unable to reset password.',422);}}
